import sys,random,itertools
sys.path.insert(0,'/workspace/submission')
import main as M

def indep_trans(op,pat,A):
    m=len(pat)
    if op=='match':
        # states 0..m, m+1 fail
        def step(k,c):
            if k<m:
                return k+1 if c==pat[k] else m+1
            return m+1
        return (m+2),0,step,m  # n,init,step,true
    if op=='startswith':
        def step(k,c):
            if k<m:
                return k+1 if c==pat[k] else m+1
            return m  # loops
        return (m+2),0,step,m
    if op=='endswith':
        if m==0:
            return 1,0,lambda k,c:0,0
        def step(k,c):
            w=pat[:k]+[c]
            for j in range(min(m,len(w)),-1,-1):
                if w[len(w)-j:]==pat[:j]:
                    return j
            return 0
        return (m+1),0,step,m
    if op=='contains':
        if m==0:
            return 1,0,lambda k,c:0,0
        def step(k,c):
            if k==m: return m
            w=pat[:k]+[c]
            for j in range(min(m,len(w)),-1,-1):
                if w[len(w)-j:]==pat[:j]:
                    return j
            return 0
        return (m+1),0,step,m

def indep_count(atoms,A):
    mons=[indep_trans(op,pat,A) for op,pat in atoms]
    init=tuple(m[1] for m in mons)
    seen={init}; dq=[init]
    while dq:
        t=dq.pop()
        for c in range(A):
            nt=tuple(mons[i][2](t[i],c) for i in range(len(mons)))
            # ensure within states
            if nt not in seen:
                seen.add(nt); dq.append(nt)
            if len(seen)>30000: return len(seen)
    return len(seen)

